"""Original editorial reading expansions; never scrape or reproduce external articles."""
EXPLAINERS = {
1: [('先把单位放在同一边', '假设每月预算从 1,000 元增加到 1,050 元，一份午餐从 20 元涨到 22 元。原来能买 50 份，现在约为 47.7 份。金额增长 5%，并没有抵消这一项价格上涨 10% 的影响。'), ('一篮子比一种商品更完整', '午餐只是支出的一部分。如果交通价格不变，住宿费用上涨，总体购买力需要按各项支出权重比较。不能用一道菜的变化代替整个消费篮子，也不能把全国价格指数直接当成每个人的生活成本。'), ('把问题带回日常', '列出最常见的三项必要开支，再看预算和价格是否使用了同一个时期。先明确“能买什么”，才知道余额变化对生活意味着什么。')],
2: [('速度变慢，位置仍在升高', '把价格想成楼层，通胀率想成向上走的速度。价格从 100 涨到 110，再以 2% 上涨到 112.2。第二年涨得慢了，价格却仍高于第一年。'), ('区分三个词', '通胀放缓指上涨速度下降；通缩通常指总体价格水平下降；某件商品降价则可能只是供需或技术变化。三个现象不能互相替代。'), ('读数字时多问一句', '这条数字是在比较去年同月还是上个月？基期价格很高，会影响同比读数。看懂比较基准，比只记住一个涨幅更可靠。')],
3: [('曲线展开的是假设', '1,000 元连续两年增长 5%，得到 1,102.5 元。第二年的利息建立在更大的基数上，这是复利的计算结构；它本身不说明现实每年都能获得 5%。'), ('平均数会藏住路径', '先涨 20% 再跌 20%，1,000 元变成 960 元。涨跌百分比的基数不同，不能简单相抵。持续投入时，投入发生的时点也会影响个人结果。'), ('把输入也看作问题', '费用、税、负收益和中途取用会改变路径。实验里尝试两组合理假设，比较差异来自哪里，而不是挑出最好看的曲线当作承诺。')],
4: [('时间也是资金的一种属性', '假设明天要支付 2,000 元维修费，而某项资产必须等待一周才能赎回。即使账面金额足够，它也不能直接解决明天的付款。能否按时使用，与总额同样重要。'), ('先识别用途，再讨论形式', '必要开支、收入稳定性、可用支持和付款时点会影响现金缓冲需求。不存在适合所有人的唯一月份数；把个人约束写出来，比机械套用数字更有用。'), ('容易忽略的边界', '可赎回不一定等于即时到账，到账时间也可能受节假日和规则影响。应急安排首先服务真实支出，不是为了追逐最高展示收益率。')],
5: [('价格比较的往往是预期差', '一家虚构公司利润从 80 增长到 100，但市场此前可能期待 120。结果比去年好、却低于预期，这两句话可以同时成立。价格还受风险、利率等条件影响。'), ('好公司与合适价格是两个问题', '公司产品受欢迎不直接证明任何买入价格都合理。对未来现金流的判断、为不确定性要求的补偿，以及已经支付的价格，需要分别讨论。'), ('避免单一原因故事', '不能仅凭公告后的涨跌倒推出所有交易者的理由。先区分披露事实、事前预期与事后解释，再承认我们通常无法完整观察市场预期。')],
6: [('用一笔未来的钱理解折现', '一年后收到 105 元，若要求收益率为 5%，当前价值是 100 元；若要求收益率提高到 10%，当前价值约为 95.45 元。未来承诺不变，今天愿意支付的金额下降。'), ('真实债券有多笔现金流', '息票和到期本金各有支付时点，要分别折现再相加。期限、息票结构、信用与流动性会改变价格敏感程度，不能认为所有债券跌幅相同。'), ('收益率不是另发的一笔利息', '票息由条款规定，市场收益率反映价格与未来现金流之间的关系。买入价格不同，即使持有相同条款的债券，计算出的收益率也可能不同。')],
7: [('先打开底层资产这一层', 'ETF 是基金交易形式，不是收益保证。若基金持有的资产价值下降，份额净值可能下降；交易所中的买卖价格还可能暂时高于或低于净值。'), ('指数也有自己的选择规则', '指数可能偏向某些行业、国家或大公司。名字里带“指数”并不自动意味着覆盖广泛，基金数量也不能直接衡量分散程度。'), ('看懂形式与策略', '有些 ETF 跟踪指数，有些采用主动管理。看基金文件中的目标、持仓、费用及交易机制，才能知道自己比较的是哪些风险。')],
8: [('分散的是依赖关系', '只持有一家公司的资产时，该公司的个别事件可能影响很大。扩大持仓范围可能减少这类单一风险，但经济衰退等共同冲击仍可能影响多数资产。'), ('数量不等于独立', '三个基金若都重仓相似公司，看起来分成三份，实际风险可能高度重叠。理解底层持仓与相关性，比数产品名称更有效。'), ('相关性也会变化', '在某些压力情景下，原本不太同步的资产也可能一起下跌。分散是管理风险的方法，不是消除所有损失的机制。')],
9: [('同一个利率，连接多个问题', '利率影响借贷成本，也影响把未来收入换算为当前价值时使用的折现率。储蓄、融资和资产定价通过这些条件相互联系。'), ('政策动作有背景', '降息可能发生在需求走弱时，也可能与通胀压力缓和有关。融资成本下降与盈利前景恶化可能同时出现，因此不能仅从一个动作推出资产价格方向。'), ('先分清事实与期待', '政策决定、市场此前预期和后续数据是三类信息。读历史决议时保留当时日期，避免把旧政策水平当作今天的条件。')],
10: [('传导是一串不同速度的反应', '政策利率改变后，金融机构可能调整部分报价，企业才会重新评估融资，家庭也会结合收入和预期决定支出。这些步骤不是按同一个时钟发生的。'), ('合同与约束会产生差异', '固定利率合同不会因为一次政策调整就立即改价。负债期限、现金缓冲和贷款可得性不同，同一政策对不同主体的影响也不同。'), ('观察多个渠道', '判断传导时，可以分别观察融资条件、信贷需求和实际支出。短期里没有看到某个结果，不足以说明所有渠道都没有作用。')],
11: [('先写清报价方向', '若 1 单位外币原本需要 7 单位本币，后来需要 7.2，支付 1,000 单位外币的成本从 7,000 变为 7,200 本币。报价方向写反，会把影响也判断反。'), ('实际结算还有一层', '展示汇率不一定是最终支付汇率。买卖点差、手续费、转换次数及结算时间，都可能影响到账或扣款金额。'), ('预算需要情景，不是预测', '留学或旅行预算可以比较几种汇率假设下的必要支出。这有助于识别预算敏感程度，不代表能够预测下一次汇率变化。')],
12: [('分母也需要检查', '市盈率把价格与盈利联系起来。若一次性处置资产抬高当期利润，计算出的市盈率可能很低，但这部分盈利未必持续。'), ('同样的倍数，不同的条件', '行业周期、增长前景、会计口径和负债结构都可能不同。跨公司比较前先确认盈利属于哪个期间、是否可比，以及是否包含异常项目。'), ('低不自动等于低估', '市场可能对未来盈利下降或更高风险要求较低价格。估值指标帮助提出问题，不能单独完成对企业价值和买卖时点的判断。')],
13: [('我们看到的是被挑选的结果', '收益截图往往只呈现一个账户、一个时期和一个片段。没有看到投入规模、失败案例或承受过的损失，就很难判断这些结果有多普遍。'), ('紧迫感会缩短核查过程', '“再不参与就来不及”容易把注意力集中在可能错过的收益上。先把信息来源、资金用途和最坏可承受后果写下来，能让问题重新具体。'), ('不行动也可以是有依据的选择', '错过某次上涨不说明先前判断必然错误；参与后获利也不自动证明决策过程可靠。评价过程时，回到当时可获得的证据。')],
14: [('买入价很醒目，却不决定未来', '某资产从 100 跌到 80，买入价会成为容易记住的参照点。但资产后续现金流、价格和风险不会因为个人希望回本而改变。'), ('先把旧结果与新选择分开', '过去损失是已经发生的结果。现在增加风险，应当有独立于“赚回来”的理由，并重新核查资金用途、期限和可能进一步损失的范围。'), ('情绪可以被记录，不必被否认', '写下最担心什么、什么新证据会改变判断，比强迫自己立即行动更有助于识别损失厌恶与锚定。这个练习不替你决定交易。')],
15: [('很多声音可能只有一个源头', '十条转发可能都来自同一张未经核验的图片。数量会增加熟悉感，却未增加十份独立证据。追溯原始来源是区分热度与证据的第一步。'), ('别人的约束不一定与你相同', '对方可能有不同的资金期限、收入来源或风险承受范围。即使信息真实，相同选择也不必适用于不同的人。'), ('主动寻找能推翻想法的信息', '问“哪些事实会让我改变判断”，再去寻找反例。只收集支持原想法的材料，可能把从众与确认偏差叠加起来。')],
16: [('低波动只回答了一类问题', '如果某项资产报价很少变化，我们仍不知道发行人能否履约、需要时能否卖出，以及长期购买力是否下降。风险并不只出现在曲线上。'), ('目标决定哪些风险重要', '短期必要支出更关心按时可用与损失幅度；较远期目标还可能关心购买力。讨论风险前，先写清资金用途和时间条件。'), ('标签需要拆开阅读', '“低风险”是相对描述，不等于本金承诺。了解产品规则、信用主体、退出安排和适用情景，才能知道这个标签遗漏了什么。')],
}
